document.getElementById('year').textContent = new Date().getFullYear();

/* ---------- Mobile nav ---------- */
const navToggle = document.getElementById('navToggle');
const mainNav = document.getElementById('mainNav');
navToggle.addEventListener('click', () => {
  const open = mainNav.classList.toggle('is-open');
  navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
});
mainNav.querySelectorAll('a').forEach(a => a.addEventListener('click', () => {
  mainNav.classList.remove('is-open');
  navToggle.setAttribute('aria-expanded', 'false');
}));

/* ---------- Scroll reveal ---------- */
const revealEls = document.querySelectorAll('.reveal');
const io = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('is-visible');
      io.unobserve(entry.target);
    }
  });
}, { threshold: 0.12, rootMargin: '0px 0px -60px 0px' });
revealEls.forEach(el => io.observe(el));

/* ---------- Active nav link on scroll ---------- */
const sections = document.querySelectorAll('main section[id]');
const navLinks = document.querySelectorAll('.nav-link');
const navIo = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    const link = document.querySelector(`.nav-link[href="#${entry.target.id}"]`);
    if (!link) return;
    if (entry.isIntersecting) {
      navLinks.forEach(l => l.classList.remove('is-active'));
      link.classList.add('is-active');
    }
  });
}, { rootMargin: '-45% 0px -50% 0px' });
sections.forEach(s => navIo.observe(s));

/* ---------- Click-to-run number counters ----------
   Every .stat-num runs its animation on click (or Enter/Space
   if focused) and stops exactly on its target value. Reads
   data-prefix / data-count / data-decimals / data-suffix.
------------------------------------------------------------- */
function runCounter(el) {
  if (el.dataset.running === '1') return;
  el.dataset.running = '1';

  const prefix = el.dataset.prefix || '';
  const suffix = el.dataset.suffix || '';
  const target = parseFloat(el.dataset.count);
  const decimals = el.dataset.decimals !== undefined
    ? parseInt(el.dataset.decimals, 10)
    : (String(el.dataset.count).includes('.') ? 1 : 0);

  const duration = 1100;
  const start = performance.now();

  function tick(now) {
    const p = Math.min((now - start) / duration, 1);
    const eased = 1 - Math.pow(1 - p, 3);
    const val = target * eased;
    el.textContent = prefix + val.toFixed(decimals) + suffix;
    if (p < 1) {
      requestAnimationFrame(tick);
    } else {
      el.textContent = prefix + target.toFixed(decimals) + suffix;
      el.dataset.running = '0';
      el.setAttribute('data-counted', 'true');
    }
  }
  requestAnimationFrame(tick);
}

document.querySelectorAll('.stat-num').forEach(el => {
  el.setAttribute('tabindex', '0');
  el.setAttribute('role', 'button');
  el.setAttribute('aria-label', 'Tap to replay this number');
  el.addEventListener('click', () => runCounter(el));
  el.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); runCounter(el); }
  });
});
// Clicking anywhere on a stat/param/total-stat card also triggers its number
document.querySelectorAll('.stat, .param, .total-stat').forEach(card => {
  card.addEventListener('click', (e) => {
    if (e.target.classList.contains('stat-num')) return;
    const num = card.querySelector('.stat-num');
    if (num) runCounter(num);
  });
});

// Numbers run automatically the moment they scroll into view.
const counterIo = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      runCounter(entry.target);
      counterIo.unobserve(entry.target);
    }
  });
}, { threshold: 0.4 });
document.querySelectorAll('.stat-num').forEach(el => counterIo.observe(el));

/* ---------- Work experience tabs ---------- */
const workTabs = document.querySelectorAll('.work-tab');
const workPanels = document.querySelectorAll('.work-panel');
workTabs.forEach(tab => {
  tab.addEventListener('click', () => {
    workTabs.forEach(t => { t.classList.remove('is-active'); t.setAttribute('aria-selected', 'false'); });
    workPanels.forEach(p => { p.classList.remove('is-active'); p.hidden = true; });

    tab.classList.add('is-active');
    tab.setAttribute('aria-selected', 'true');
    const target = document.getElementById(tab.dataset.target);
    target.hidden = false;
    target.classList.add('is-active');
    // Numbers inside a freshly-revealed panel weren't visible to the
    // scroll observer while hidden — run them now that the tab is open.
    target.querySelectorAll('.stat-num').forEach(el => {
      if (!el.hasAttribute('data-counted')) runCounter(el);
    });
  });
});

/* ---------- Lightbox (shared: images, videos, carousels, PDFs) ---------- */
const lightbox = document.getElementById('lightbox');
const lightboxInner = document.getElementById('lightboxInner');
const lightboxClose = document.getElementById('lightboxClose');

function openLightbox(html) {
  lightboxInner.innerHTML = html;
  lightbox.hidden = false;
  document.body.style.overflow = 'hidden';
}
function closeLightbox() {
  lightbox.hidden = true;
  lightboxInner.innerHTML = '';
  document.body.style.overflow = '';
}
lightboxClose.addEventListener('click', closeLightbox);
lightbox.addEventListener('click', (e) => { if (e.target === lightbox) closeLightbox(); });
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && !lightbox.hidden) closeLightbox(); });

/* ---------- Certifications: click name -> PDF pops out in lightbox ---------- */
document.querySelectorAll('.cert-badge').forEach(badge => {
  badge.addEventListener('click', () => {
    const pdf = badge.dataset.pdf;
    const title = badge.dataset.title;
    openLightbox(`
      <iframe src="${pdf}" title="${title}" style="width:min(720px,90vw); height:82vh; border:0; border-radius:10px; background:#fff;"></iframe>
      <p class="lightbox-caption">${title} &nbsp;·&nbsp; <a href="${pdf}" target="_blank" rel="noopener" style="color:#E4CFA0;">Open in new tab &#8599;</a></p>
    `);
  });
});

