const grid = document.getElementById('creativeGrid');
const playIcon = `<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7Z"/></svg>`;

// If a creative image/video fails to load (e.g. broken path after
// deployment), show a visible, labelled placeholder instead of a
// blank tile — makes the problem obvious rather than invisible.
window.__mediaFallback = function (el, label) {
  const wrap = document.createElement('div');
  wrap.className = 'media-error';
  wrap.innerHTML = `
    <svg viewBox="0 0 24 24"><path d="M4 4h16v16H4Z" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="M4 16l5-5 4 4 3-3 4 4" fill="none" stroke="currentColor" stroke-width="1.6"/><circle cx="9" cy="9" r="1.6"/></svg>
    <span>Couldn't load<br>${label}</span>
  `;
  el.replaceWith(wrap);
};

creatives.forEach((c, i) => {
  const card = document.createElement('div');
  card.dataset.cat = c.cat;

  if (c.type === 'video') {
    card.className = 'creative-card';
    card.innerHTML = `
      <span class="type-tag">Video</span>
      <img src="${c.poster}" alt="${c.name}" loading="lazy" onerror="window.__mediaFallback(this, '${c.name}')">
      <span class="play-badge">${playIcon}</span>
      <div class="creative-tag"><span>${c.name}</span></div>
    `;
    card.addEventListener('click', () => {
      openLightbox(`<video src="${c.src}" controls autoplay playsinline onerror="window.__mediaFallback(this, '${c.name} (video)')"></video><p class="lightbox-caption">${c.name}</p>`);
    });
  } else if (c.type === 'image') {
    card.className = 'creative-card';
    card.innerHTML = `
      <span class="type-tag">${c.cat === 'reviews' ? 'Review' : 'Static'}</span>
      <img src="${c.src}" alt="${c.name}" loading="lazy" onerror="window.__mediaFallback(this, '${c.name}')">
      <div class="creative-tag"><span>${c.name}</span></div>
    `;
    card.addEventListener('click', () => {
      openLightbox(`<img src="${c.src}" alt="${c.name}" onerror="window.__mediaFallback(this, '${c.name}')"><p class="lightbox-caption">${c.name}</p>`);
    });
  } else if (c.type === 'carousel') {
    card.className = 'creative-card creative-card--carousel';
    let frameIdx = 0;
    const framesHtml = c.frames.map((f, idx) => `<img src="${f}" class="${idx === 0 ? 'is-active' : ''}" alt="${c.name} frame ${idx + 1}" loading="lazy">`).join('');
    const dotsHtml = c.frames.map((f, idx) => `<span class="${idx === 0 ? 'is-active' : ''}"></span>`).join('');
    card.innerHTML = `
      <span class="type-tag">Carousel</span>
      <div class="mini-carousel">
        <div class="mini-carousel-track">${framesHtml}</div>
        <button class="mini-carousel-nav mini-carousel-nav--prev" aria-label="Previous frame">&#8249;</button>
        <button class="mini-carousel-nav mini-carousel-nav--next" aria-label="Next frame">&#8250;</button>
        <div class="mini-carousel-dots">${dotsHtml}</div>
      </div>
      <div class="creative-tag"><span>${c.name}</span></div>
    `;
    const track = card.querySelector('.mini-carousel-track');
    const dots = card.querySelectorAll('.mini-carousel-dots span');
    function showFrame(idx) {
      frameIdx = (idx + c.frames.length) % c.frames.length;
      track.querySelectorAll('img').forEach((im, i2) => im.classList.toggle('is-active', i2 === frameIdx));
      dots.forEach((d, i2) => d.classList.toggle('is-active', i2 === frameIdx));
    }
    card.querySelector('.mini-carousel-nav--prev').addEventListener('click', (e) => { e.stopPropagation(); showFrame(frameIdx - 1); });
    card.querySelector('.mini-carousel-nav--next').addEventListener('click', (e) => { e.stopPropagation(); showFrame(frameIdx + 1); });
    card.addEventListener('click', () => openLightboxCarousel(c.frames, c.name, frameIdx));
  }

  grid.appendChild(card);
});

function openLightboxCarousel(frames, name, startIdx) {
  let idx = startIdx || 0;
  openLightbox(`
    <div class="lb-carousel">
      <button class="lb-nav lb-nav--prev" aria-label="Previous">&#8249;</button>
      <div class="lb-carousel-imgwrap"><img src="${frames[idx]}" alt="${name}"></div>
      <button class="lb-nav lb-nav--next" aria-label="Next">&#8250;</button>
    </div>
    <div class="lb-dots">${frames.map((f, i) => `<span class="${i === idx ? 'is-active' : ''}"></span>`).join('')}</div>
    <p class="lightbox-caption">${name}</p>
  `);
  const img = lightboxInner.querySelector('.lb-carousel-imgwrap img');
  const dots = lightboxInner.querySelectorAll('.lb-dots span');
  function render() {
    img.src = frames[idx];
    dots.forEach((d, i) => d.classList.toggle('is-active', i === idx));
  }
  lightboxInner.querySelector('.lb-nav--prev').addEventListener('click', () => { idx = (idx - 1 + frames.length) % frames.length; render(); });
  lightboxInner.querySelector('.lb-nav--next').addEventListener('click', () => { idx = (idx + 1) % frames.length; render(); });
}

