/* Lightweight matcher: exact-phrase hits score highest, individual
   word overlaps add smaller partial credit so rephrased questions
   still land on a reasonable answer. */
function findAnswer(question) {
  const q = question.toLowerCase().trim();
  const qWords = q.split(/[^a-z0-9]+/).filter(Boolean);
  let best = null, bestScore = 0;

  KB.forEach(entry => {
    let score = 0;
    entry.keys.forEach(k => {
      if (q.includes(k)) score += k.length * 3;
      k.split(' ').forEach(w => { if (w.length > 2 && qWords.includes(w)) score += w.length; });
    });
    if (score > bestScore) { bestScore = score; best = entry; }
  });

  if (best && bestScore >= 3) return best.a;
  return `I don't have a confident answer for that from the portfolio — try asking about work
  experience, the Rareduft case study, skills, certifications, education, ROAS/spend numbers, or
  how to contact Deepak. For anything else, reach him directly on
  <a href="https://wa.me/918088977454" target="_blank" rel="noopener">WhatsApp</a>.`;
}

