function addMsg(text, who) {
  const div = document.createElement('div');
  div.className = `ask-msg ask-msg--${who}`;
  div.innerHTML = text;
  askBody.appendChild(div);
  askBody.scrollTop = askBody.scrollHeight;
}

function askQuestion(q) {
  if (!q.trim()) return;
  addMsg(q, 'user');
  setTimeout(() => addMsg(findAnswer(q), 'bot'), 260);
}

askForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const q = askInput.value;
  askInput.value = '';
  askQuestion(q);
});

askChips.querySelectorAll('.ask-chip').forEach(chip => {
  chip.addEventListener('click', () => askQuestion(chip.dataset.q));
});
